"use client"; import {useEffect,useState} from "react"; import {apiUrl} from "./api-base"; export function useFundings(campaignId:string,pollMs=10_000){const [data,setData]=useState<unknown>(null);useEffect(()=>{let mounted=true;const load=async()=>{const r=await fetch(apiUrl(`/api/v1/funding/campaigns/${encodeURIComponent(campaignId)}`),{cache:"no-store"});if(r.ok&&mounted){const b=await r.json();setData(b.data)}};void load();const id=setInterval(()=>void load(),Math.min(15000,Math.max(5000,pollMs)));return()=>{mounted=false;clearInterval(id)}},[campaignId,pollMs]);return data}
